import{_ as e,o as n,c as o,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"07 — Kết nối Mạng xã hội, Lên lịch & Xuất bản Đa Nền tảng (Publishing & Social)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/07-publishing-social.md","filePath":"ba/07-publishing-social.md"}'),c={name:"ba/07-publishing-social.md"};function a(i,t,l,s,h,r){return n(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="_07-—-ket-noi-mang-xa-hoi-len-lich-xuat-ban-đa-nen-tang-publishing-social" tabindex="-1">07 — Kết nối Mạng xã hội, Lên lịch &amp; Xuất bản Đa Nền tảng (Publishing &amp; Social) <a class="header-anchor" href="#_07-—-ket-noi-mang-xa-hoi-len-lich-xuat-ban-đa-nen-tang-publishing-social" aria-label="Permalink to &quot;07 — Kết nối Mạng xã hội, Lên lịch &amp; Xuất bản Đa Nền tảng (Publishing &amp; Social)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./06-ai-features.html">← 06 - AI Features</a> · <a href="./08-subscription-billing.html">Tiếp: 08 - Subscription &amp; Billing →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.8 Publishing &amp; Social</code> — 15 FR (<code>3.8.1</code> – <code>3.8.15</code>)</strong> | <code>UC-107</code> – <code>UC-121</code> · Use Cases chi tiết: <a href="./use-cases/06-publishing-social.html">use-cases/06-publishing-social.md</a> · Đặc tả SRS: <a href="./../feature/srs/07-publishing-social/README.html">07-publishing-social</a>. &gt; Tuân thủ nghiêm ngặt quy tắc <strong>4 nền tảng mạng xã hội chuẩn: Facebook, Instagram, TikTok, và Threads</strong> (không có Zalo OA, không có YouTube theo <code>AGENTS.md</code>). &gt; <em>(Lưu ý: Nhóm Danh bạ Đối tác truyền thông bên thứ ba đã được chuẩn hóa sang mục <code>3.7.15</code>–<code>3.7.19</code> trong <a href="./06-ai-features.html">06-ai-features.md</a>).</em></p><hr><h2 id="_1-bang-tong-hop-15-yeu-cau-chuc-nang-chuan-3-8-1-–-3-8-15" tabindex="-1">1. Bảng Tổng hợp 15 Yêu cầu Chức năng Chuẩn (<code>3.8.1</code> – <code>3.8.15</code>) <a class="header-anchor" href="#_1-bang-tong-hop-15-yeu-cau-chuc-nang-chuan-3-8-1-–-3-8-15" aria-label="Permalink to &quot;1. Bảng Tổng hợp 15 Yêu cầu Chức năng Chuẩn (`3.8.1` – `3.8.15`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (141-FR Baseline)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.8.1</code></strong></td><td style="text-align:center;"><code>UC-107</code></td><td style="text-align:left;"><strong>Connect Social Account</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Kết nối tài khoản mạng xã hội chính thức (Facebook Page, Instagram Business, TikTok Creator/Business, Threads) vào Workspace qua OAuth 2.0, kiểm tra giới hạn kênh theo gói và mã hóa AES-256 token (<code>BR-20</code>, <code>BR-53</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.2</code></strong></td><td style="text-align:center;"><code>UC-108</code></td><td style="text-align:left;"><strong>Disconnect Account</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Ngắt kết nối một tài khoản mạng xã hội khỏi Workspace; thu hồi khóa OAuth đã lưu, dừng các lịch đăng tự động đang chờ và giữ nguyên lịch sử bài đã đăng (<code>BR-20</code>, <code>BR-53</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.3</code></strong></td><td style="text-align:center;"><code>UC-109</code></td><td style="text-align:left;"><strong>View Dashboard Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem bảng điều khiển tổng hợp các bài đã xuất bản thành công trên 4 mạng xã hội của Workspace cùng biểu đồ phân bổ và hiệu suất tương tác (<code>BR-20</code>, <code>BR-57</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.4</code></strong></td><td style="text-align:center;"><code>UC-110</code></td><td style="text-align:left;"><strong>View Posted Detail</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem chi tiết một bài đăng đã xuất bản kèm đường dẫn trực tiếp (<code>permalink</code>) và số liệu tương tác chi tiết (<code>Reactions</code>, <code>Comments</code>, <code>Shares</code>, <code>Views</code>, <code>BR-20</code>, <code>BR-57</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.5</code></strong></td><td style="text-align:center;"><code>UC-111</code></td><td style="text-align:left;"><strong>Preview Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem trước giao diện hiển thị (<code>Mockup Preview</code> trên Desktop &amp; Mobile) của Facebook Feed/Story/Reels, Instagram Post/Reels/Story, TikTok Video và Threads Post kèm kiểm tra giới hạn ký tự và tỷ lệ khung hình (<code>BR-55</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.6</code></strong></td><td style="text-align:center;"><code>UC-112</code></td><td style="text-align:left;"><strong>Schedule Platform Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Lên lịch xuất bản tự động bài viết đã đạt <code>APPROVED</code> (<code>BR-54</code>) vào ngày giờ cụ thể (chuẩn hóa theo Timezone của Workspace <code>BR-22</code>, cách hiện tại tối thiểu 5 phút <code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.7</code></strong></td><td style="text-align:center;"><code>UC-113</code></td><td style="text-align:left;"><strong>Track Post Status</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Theo dõi trạng thái tiến trình xuất bản thời gian thực (<code>PENDING</code>, <code>IN_PROGRESS</code>, <code>DONE</code> / <code>PUBLISHED</code>, <code>FAIL</code>) kèm nhật ký phản hồi API, tự động retry tối đa 3 lần và nút <code>Retry</code> thủ công (<code>BR-20</code>, <code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.8</code></strong></td><td style="text-align:center;"><code>UC-114</code></td><td style="text-align:left;"><strong>Publish Facebook Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản bài viết tiêu chuẩn (văn bản, bộ ảnh hoặc video) lên Facebook Page qua Meta Graph API (<code>BR-54</code>–<code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.9</code></strong></td><td style="text-align:center;"><code>UC-115</code></td><td style="text-align:left;"><strong>Publish Facebook Story</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản tin ngắn 24 giờ (ảnh hoặc video dọc <code>9:16</code>) lên Facebook Page Story qua Meta Graph API (<code>BR-54</code>–<code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.10</code></strong></td><td style="text-align:center;"><code>UC-116</code></td><td style="text-align:left;"><strong>Publish Facebook Reels</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản video ngắn dọc (<code>9:16</code>, thời lượng 3–90 giây) lên Facebook Page thông qua Meta Reels Publishing API 2 pha (<code>BR-54</code>–<code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.11</code></strong></td><td style="text-align:center;"><code>UC-117</code></td><td style="text-align:left;"><strong>Publish Instagram Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản bài đăng ảnh đơn hoặc bộ ảnh xoay vòng (Carousel) kèm caption và hashtag lên tài khoản Instagram Business qua Instagram Graph API (<code>BR-54</code>–<code>BR-57</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.12</code></strong></td><td style="text-align:center;"><code>UC-118</code></td><td style="text-align:left;"><strong>Publish Instagram Reels</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản video ngắn dọc lên Instagram Reels kèm ảnh bìa (<code>cover frame</code>) và caption qua Instagram Graph API (<code>BR-54</code>–<code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.13</code></strong></td><td style="text-align:center;"><code>UC-119</code></td><td style="text-align:left;"><strong>Publish Instagram Story</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản hình ảnh hoặc video ngắn 24 giờ tỷ lệ <code>9:16</code> lên Instagram Business Story qua Instagram Graph API (<code>BR-54</code>–<code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.14</code></strong></td><td style="text-align:center;"><code>UC-120</code></td><td style="text-align:left;"><strong>Publish TikTok Video</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản video ngắn lên tài khoản TikTok thông qua TikTok Content Posting API v2 (chunked upload, tùy chọn quyền riêng tư và cho phép Duet/Stitch/Comment, <code>BR-54</code>–<code>BR-56</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.15</code></strong></td><td style="text-align:center;"><code>UC-121</code></td><td style="text-align:left;"><strong>Publish Threads Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản bài viết văn bản (≤ 500 ký tự) kèm hình ảnh hoặc video lên nền tảng Threads qua Threads Publishing API (<code>BR-54</code>–<code>BR-56</code>).</td></tr></tbody></table><hr><h2 id="_2-đac-ta-nghiep-vu-ket-noi-tai-khoan-mang-xa-hoi-3-8-1-–-3-8-2" tabindex="-1">2. Đặc tả Nghiệp vụ Kết nối Tài khoản Mạng xã hội (<code>3.8.1</code> – <code>3.8.2</code>) <a class="header-anchor" href="#_2-đac-ta-nghiep-vu-ket-noi-tai-khoan-mang-xa-hoi-3-8-1-–-3-8-2" aria-label="Permalink to &quot;2. Đặc tả Nghiệp vụ Kết nối Tài khoản Mạng xã hội (`3.8.1` – `3.8.2`)&quot;">​</a></h2><h3 id="_2-1-quyen-ket-noi-trong-che-đo-agency-vs-personal" tabindex="-1">2.1. Quyền Kết nối trong Chế độ <code>AGENCY</code> vs. <code>PERSONAL</code> <a class="header-anchor" href="#_2-1-quyen-ket-noi-trong-che-đo-agency-vs-personal" aria-label="Permalink to &quot;2.1. Quyền Kết nối trong Chế độ `AGENCY` vs. `PERSONAL`&quot;">​</a></h3><ul><li><strong>Trong Chế độ <code>AGENCY</code> (<code>workspaceMode = &quot;AGENCY&quot;</code>)</strong>: <ul><li>Cả <strong><code>Client</code></strong> (tại <code>Client Portal</code> hoặc trang kết nối) và <strong><code>Manager</code></strong> (cùng <code>Owner</code>) đều có quyền thực hiện OAuth kết nối tài khoản MXH của thương hiệu vào Workspace.</li></ul></li><li><strong>Trong Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</strong>: <ul><li>Chủ không gian (<strong><code>Owner</code> / <code>Manager</code></strong>) kết nối trực tiếp các kênh Facebook, Instagram, TikTok, Threads cá nhân của mình tại <code>/workspaces/:id/social-accounts</code> (hoặc bấm từ <strong>Bệ phóng Sáng tạo Cá nhân — Personal Quick Launchpad</strong> trên Dashboard) mà không cần thông qua bất kỳ tài khoản <code>Client</code> nào.</li></ul></li></ul><h3 id="_2-2-quan-ly-vong-đoi-token-oauth" tabindex="-1">2.2. Quản lý Vòng đời Token OAuth <a class="header-anchor" href="#_2-2-quan-ly-vong-đoi-token-oauth" aria-label="Permalink to &quot;2.2. Quản lý Vòng đời Token OAuth&quot;">​</a></h3><ul><li>Mọi <code>accessToken</code> và <code>refreshToken</code> của 4 nền tảng được mã hóa an toàn trước khi lưu trữ và được quản lý bởi <code>brandhub-publisher-service</code> / <code>brandhub-business-service</code>.</li><li>Khi token sắp hết hạn, dịch vụ tự động gia hạn ngầm (<code>Token Refresh</code>); nếu người dùng đổi mật khẩu MXH hoặc thu hồi quyền từ phía nền tảng khiến token hết hiệu lực (<code>EXPIRED</code>), hệ thống hiển thị cảnh báo trạng thái cần kết nối lại (<code>Reconnect</code>).</li></ul><hr><h2 id="_3-quy-trinh-len-lich-phe-duyet-xuat-ban-đa-nen-tang-3-8-5-–-3-8-15" tabindex="-1">3. Quy trình Lên lịch, Phê duyệt &amp; Xuất bản Đa Nền tảng (<code>3.8.5</code> – <code>3.8.15</code>) <a class="header-anchor" href="#_3-quy-trinh-len-lich-phe-duyet-xuat-ban-đa-nen-tang-3-8-5-–-3-8-15" aria-label="Permalink to &quot;3. Quy trình Lên lịch, Phê duyệt &amp; Xuất bản Đa Nền tảng (`3.8.5` – `3.8.15`)&quot;">​</a></h2><h3 id="_3-1-đieu-kien-tien-quyet-đe-xuat-ban-publishing-gate" tabindex="-1">3.1. Điều kiện Tiên quyết Để Xuất bản (<code>Publishing Gate</code>) <a class="header-anchor" href="#_3-1-đieu-kien-tien-quyet-đe-xuat-ban-publishing-gate" aria-label="Permalink to &quot;3.1. Điều kiện Tiên quyết Để Xuất bản (`Publishing Gate`)&quot;">​</a></h3><p>Để đảm bảo không bao giờ đăng nhầm nội dung chưa được phê duyệt lên mạng xã hội:</p><ol><li><strong>Quyền cấu hình kênh &amp; lịch đăng (<code>POST.CHANNELS</code> / <code>VIDEO.CHANNELS</code>)</strong>: <ul><li>Người giữ vai trò <code>POST_PUBLISHING</code> (với Task <code>POST</code>), <code>VIDEO_PUBLISH</code> (với Task <code>SHORT_VIDEO</code>), Điều phối viên (<code>assigneeId</code>), hoặc <code>Manager</code> / <code>Owner</code> có thể chọn kênh xuất bản và đặt giờ đăng dự kiến (<code>scheduledAt</code>) bất cứ lúc nào khi phần còn mở.</li><li>Riêng công việc loại <code>SHORT_VIDEO</code> chỉ cho phép chọn các kênh hỗ trợ định dạng video ngắn: <strong>TikTok (<code>3.8.14</code>), Instagram Reels (<code>3.8.12</code>), Facebook Reels (<code>3.8.10</code>)</strong>.</li></ul></li><li><strong>Điều kiện mở khóa Xuất bản thật (<code>Publish Now</code> &amp; <code>PostSchedulePublishJob</code>)</strong>: <ul><li>Lệnh xuất bản thật sang <code>brandhub-publisher-service</code> (qua hàng đợi RabbitMQ <code>PublishJobMessage</code>) <strong>chỉ được kích hoạt khi Công việc cha đã hoàn tất phê duyệt</strong>: <ul><li><code>task.status == TaskStatus.FINISHED</code> <strong>VÀ</strong> <code>task.lastSubmission.outcome == ApprovalOutcome.APPROVED</code>.</li></ul></li><li><strong>Ở chế độ <code>AGENCY</code></strong>: Đạt được sau khi <code>Manager</code> duyệt nội bộ và <code>Client</code> duyệt đủ các phần sản phẩm đầu ra (<code>CLIENT_APPROVED</code>).</li><li><strong>Ở chế độ <code>PERSONAL</code></strong>: Đạt được <strong>ngay lập tức chỉ với 1 cú nhấp chuột</strong> khi chủ không gian bấm nút <strong>&quot;Hoàn tất &amp; Duyệt ngay (<code>Self-Approve</code>)&quot;</strong> (<code>POST /api/v1/workspaces/{id}/tasks/{taskId}/self-approve</code>).</li></ul></li></ol><h3 id="_3-2-co-che-huy-lich-tu-đong-khi-noi-dung-bi-tra-lai" tabindex="-1">3.2. Cơ chế Hủy lịch Tự động Khi Nội dung Bị Trả lại <a class="header-anchor" href="#_3-2-co-che-huy-lich-tu-đong-khi-noi-dung-bi-tra-lai" aria-label="Permalink to &quot;3.2. Cơ chế Hủy lịch Tự động Khi Nội dung Bị Trả lại&quot;">​</a></h3><ul><li>Nếu một bài viết đã được đặt lịch (<code>status = SCHEDULED</code>), nhưng trước giờ đăng mà <code>Client</code> hoặc <code>Manager</code> bấm <strong>Trả lại (<code>Return</code>)</strong> một phần nội dung để yêu cầu chỉnh sửa: <ul><li>Hệ thống tự động đưa Task cha về <code>IN_PROGRESS</code> và gọi <code>PostService.cancelTaskSchedule(workspaceId, taskId)</code> để chuyển bài viết về <code>DRAFT</code>, xóa <code>scheduledAt</code>.</li><li>Nhờ đó, <code>PostSchedulePublishJob</code> (quét định kỳ mỗi 30 giây) sẽ tự động bỏ qua bài viết đó cho đến khi nội dung được sửa, duyệt lại và đặt lịch mới.</li></ul></li></ul><h3 id="_3-3-quy-chuan-ky-thuat-theo-tung-đinh-dang-xuat-ban-3-8-8-–-3-8-15" tabindex="-1">3.3. Quy chuẩn Kỹ thuật Theo Từng Định dạng Xuất bản (<code>3.8.8</code> – <code>3.8.15</code>) <a class="header-anchor" href="#_3-3-quy-chuan-ky-thuat-theo-tung-đinh-dang-xuat-ban-3-8-8-–-3-8-15" aria-label="Permalink to &quot;3.3. Quy chuẩn Kỹ thuật Theo Từng Định dạng Xuất bản (`3.8.8` – `3.8.15`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:left;">Định dạng Xuất bản</th><th style="text-align:center;">Nền tảng</th><th style="text-align:left;">Yêu cầu Nội dung &amp; Media Đầu vào</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.8.8</code></strong></td><td style="text-align:left;"><strong>Publish Facebook Post</strong></td><td style="text-align:center;">Facebook Page</td><td style="text-align:left;">Văn bản (<code>caption</code> ≤ 63.206 ký tự), kèm tùy chọn 1–10 ảnh (JPG/PNG/WebP) hoặc 1 video.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.9</code></strong></td><td style="text-align:left;"><strong>Publish Facebook Story</strong></td><td style="text-align:center;">Facebook Page</td><td style="text-align:left;">Bắt buộc 1 ảnh hoặc 1 video ngắn dọc (<code>9:16</code>) hiển thị trong 24 giờ.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.10</code></strong></td><td style="text-align:left;"><strong>Publish Facebook Reels</strong></td><td style="text-align:center;">Facebook Page</td><td style="text-align:left;">Bắt buộc 1 video dọc (<code>9:16</code> khuyến nghị, thời lượng 3s–90s, MP4/MOV) + mô tả ngắn.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.11</code></strong></td><td style="text-align:left;"><strong>Publish Instagram Post</strong></td><td style="text-align:center;">Instagram Business</td><td style="text-align:left;">Bắt buộc ít nhất 1 ảnh hoặc album Carousel (tối đa 10 media) + <code>caption</code> (≤ 2.200 ký tự, tối đa 30 hashtag).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.12</code></strong></td><td style="text-align:left;"><strong>Publish Instagram Reels</strong></td><td style="text-align:center;">Instagram Business</td><td style="text-align:left;">Bắt buộc 1 video dọc (MP4/MOV, tối đa 15 phút, khuyến nghị ≤ 90s) + <code>caption</code> + ảnh bìa tùy chọn.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.13</code></strong></td><td style="text-align:left;"><strong>Publish Instagram Story</strong></td><td style="text-align:center;">Instagram Business</td><td style="text-align:left;">Bắt buộc 1 ảnh hoặc 1 video ngắn dọc (<code>9:16</code>) hiển thị trong 24 giờ.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.14</code></strong></td><td style="text-align:left;"><strong>TikTok Video</strong></td><td style="text-align:center;">TikTok</td><td style="text-align:left;">Bắt buộc 1 video (MP4/WebM/MOV, 3s–10 phút) + tiêu đề/caption (≤ 2.200 ký tự).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.15</code></strong></td><td style="text-align:left;"><strong>Threads Post</strong></td><td style="text-align:center;">Threads</td><td style="text-align:left;">Văn bản (≤ 500 ký tự mỗi bài) và/hoặc ảnh/video đính kèm.</td></tr></tbody></table><hr><h2 id="_4-bang-tham-chieu-quy-tac-nghiep-vu-br-53-–-br-57" tabindex="-1">4. Bảng Tham chiếu Quy tắc Nghiệp vụ (<code>BR-53</code> – <code>BR-57</code>) <a class="header-anchor" href="#_4-bang-tham-chieu-quy-tac-nghiep-vu-br-53-–-br-57" aria-label="Permalink to &quot;4. Bảng Tham chiếu Quy tắc Nghiệp vụ (`BR-53` – `BR-57`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-53</code></td><td style="text-align:left;"><strong>Mã hóa <code>AES-256-GCM</code> &amp; Giới hạn Kênh OAuth</strong></td><td style="text-align:left;">Chỉ hỗ trợ đúng <strong>4 nền tảng chuẩn (<code>FACEBOOK</code>, <code>INSTAGRAM</code>, <code>TIKTOK</code>, <code>THREADS</code>)</strong>; toàn bộ OAuth token lưu trong <code>social_accounts</code> được mã hóa <code>AES-256-GCM</code> (<code>CryptoUtils</code>), tự động làm mới trước hạn 7 ngày (<code>TokenRefreshScheduler</code>) và hủy lịch đăng chờ khi ngắt kết nối kênh.</td><td style="text-align:left;"><code>3.8.1</code>, <code>3.8.2</code></td></tr><tr><td style="text-align:center;"><code>BR-54</code></td><td style="text-align:left;"><strong>Cổng Chặn Phê duyệt Trước Xuất bản (<code>Approval Gate</code>)</strong></td><td style="text-align:left;">Tuyệt đối không cho phép đặt lịch kích hoạt hoặc xuất bản bài viết chưa đạt trạng thái <code>APPROVED</code> (qua đủ chuỗi <code>Creator -&gt; Manager -&gt; Client</code> ở chế độ <code>AGENCY</code>, hoặc <code>Self-Approve</code> ở chế độ <code>PERSONAL</code>).</td><td style="text-align:left;"><code>3.8.6</code>, <code>3.8.8</code>–<code>3.8.15</code></td></tr><tr><td style="text-align:center;"><code>BR-55</code></td><td style="text-align:left;"><strong>Kiểm tra Tương thích Định dạng Trước Xuất bản</strong></td><td style="text-align:left;">Kiểm tra nghiêm ngặt giới hạn ký tự, số lượng tệp, định dạng video/ảnh, tỷ lệ khung hình (<code>9:16</code> cho Story/Reels/TikTok) và chặn tệp gắn nhãn <code>RAW</code> ngay từ màn hình <code>Preview Post</code> (<code>3.8.5</code>).</td><td style="text-align:left;"><code>3.8.5</code>, <code>3.8.8</code>–<code>3.8.15</code></td></tr><tr><td style="text-align:center;"><code>BR-56</code></td><td style="text-align:left;"><strong>Đặt lịch Tương lai, Khóa Chống Trùng &amp; Thử lại Bậc thang</strong></td><td style="text-align:left;">Giờ hẹn đăng (<code>scheduledAt</code>) phải lớn hơn thời điểm hiện tại ít nhất <strong>5 phút</strong> (theo múi giờ IANA của Workspace); tiến trình tiêu thụ RabbitMQ khóa theo cặp <code>processingPostIds:{postId}:{platform}</code> (<code>TTL 30m</code>) và tự động thử lại qua 3 hàng đợi trễ <code>1m → 5m → 15m</code> trước khi chuyển vào <code>publisher.job.dlq</code>.</td><td style="text-align:left;"><code>3.8.6</code>–<code>3.8.15</code></td></tr><tr><td style="text-align:center;"><code>BR-57</code></td><td style="text-align:left;"><strong>Bảo toàn Nhật ký &amp; Số liệu Bài Đã Đăng</strong></td><td style="text-align:left;">Các bản ghi <code>posts</code> đã xuất bản và nhật ký <code>publish_logs</code> được lưu trữ bền vững kèm <code>permalink</code> gốc kể cả sau khi tài khoản mạng xã hội bị ngắt kết nối khỏi Workspace.</td><td style="text-align:left;"><code>3.8.2</code>–<code>3.8.4</code>, <code>3.8.7</code></td></tr></tbody></table><hr><h2 id="_5-so-đo-đieu-phoi-xuat-ban-bat-đong-bo-business-service-↔-rabbitmq-↔-publisher-service" tabindex="-1">5. Sơ đồ Điều phối Xuất bản Bất đồng bộ (<code>business-service</code> ↔ <code>RabbitMQ</code> ↔ <code>publisher-service</code>) <a class="header-anchor" href="#_5-so-đo-đieu-phoi-xuat-ban-bat-đong-bo-business-service-↔-rabbitmq-↔-publisher-service" aria-label="Permalink to &quot;5. Sơ đồ Điều phối Xuất bản Bất đồng bộ (`business-service` ↔ `RabbitMQ` ↔ `publisher-service`)&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BIZ[&quot;brandhub-business-service&lt;br/&gt;(PostService + PostSchedulePublishJob)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q[&quot;RabbitMQ Direct Exchange&lt;br/&gt;publisher.job.queue&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CON[&quot;brandhub-publisher-service&lt;br/&gt;PublishJobConsumer + Redis Lock&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ADP[&quot;4 SocialPublishAdapters&lt;br/&gt;(Facebook, Instagram, TikTok, Threads)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RTY[&quot;Retry Queues (TTL + DLX)&lt;br/&gt;1m → 5m → 15m → publisher.job.dlq&quot;]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BIZ --&gt;|&quot;1 job per target platform&quot;| Q --&gt; CON</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CON --&gt;|&quot;Decrypt AES-256-GCM token&quot;| ADP</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ADP --&gt;|&quot;Callback status + permalink&quot;| BIZ</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CON -. &quot;Transient API / 5xx error&quot; .-&gt; RTY -. &quot;Re-route&quot; .-&gt; Q</span></span></code></pre></div><p>(Xem chi tiết quyết định kiến trúc tại <a href="./../adr/adr-003-rabbitmq.html">ADR-003 RabbitMQ Async Publishing</a>).</p>',27)])])}const b=e(c,[["render",a]]);export{u as __pageData,b as default};
